library(haven)
library(dplyr)
library(tidyr)
library(readr)
library(labelled)

# Create output directory if it doesn't exist
if (!dir.exists("data/output")) {
  dir.create("data/output", recursive = TRUE)
}

# Load all data files
wave1 <- read_delim("data/input/wave_one_lsype_young_person_2020.tab", delim = "\t")
wave4 <- read_delim("data/input/wave_four_lsype_young_person_2020.tab", delim = "\t")
ns8_main <- read_delim("data/input/ns8_2015_main_interview.tab", delim = "\t")
ns8_derived <- read_delim("data/input/ns8_2015_derived.tab", delim = "\t")
ns9_main <- read_delim("data/input/ns9_2022_main_interview.tab", delim = "\t")
ns9_derived <- read_delim("data/input/ns9_2022_derived_variables.tab", delim = "\t")

# Merge all datasets
full_data <- wave1 %>%
  full_join(wave4, by = "NSID") %>%
  full_join(ns8_main, by = "NSID") %>%
  full_join(ns8_derived, by = "NSID") %>%
  full_join(ns9_main, by = "NSID") %>%
  full_join(ns9_derived, by = "NSID")

# Define the mapping from W8VCQU variables to NVQ tiers
voc_mapping <- c(
  "W8VCQU0A" = 2, "W8VCQU0B" = 2, "W8VCQU0C" = 2, "W8VCQU0D" = 2, "W8VCQU0E" = 2,
  "W8VCQU0F" = 2, "W8VCQU0G" = 2, "W8VCQU0H" = 2, "W8VCQU0I" = 2, "W8VCQU0J" = 1,
  "W8VCQU0K" = 1, "W8VCQU0L" = 2, "W8VCQU0M" = 1, "W8VCQU0N" = 1, "W8VCQU0O" = 1,
  "W8VCQU0P" = 2, "W8VCQU0Q" = -8, "W8VCQU0R" = -9
)

# Create W8VCQU tier mapping data frame
voc_tier_df <- data.frame(
  var = names(voc_mapping),
  tier = voc_mapping,
  stringsAsFactors = FALSE
)

# Convert W8VCQU variables to tiers using vectorized approach
for (i in 1:nrow(voc_tier_df)) {
  var_name <- voc_tier_df$var[i]
  tier_val <- voc_tier_df$tier[i]

  full_data[[var_name]] <- case_when(
    full_data[[var_name]] %in% c(-9, -9.0) ~ -9,
    full_data[[var_name]] %in% c(-8, -8.0) ~ -8,
    full_data[[var_name]] %in% c(-1, -1.0) ~ -1,
    full_data[[var_name]] == 0 ~ tier_val,
    full_data[[var_name]] == 1 ~ tier_val,
    TRUE ~ as.integer(full_data[[var_name]])
  )
}

# Derive educ25_academic from W8DHANVQH
full_data <- full_data %>%
  mutate(
    educ25_academic = case_when(
      W8DHANVQH %in% 5:4 ~ 0,
      W8DHANVQH %in% 1:3 ~ 1,
      W8DHANVQH == 95 ~ 3,
      W8DHANVQH == 96 ~ 4,
      is.na(W8DHANVQH) | W8DHANVQH %in% -1:-9 ~ -3
    )
  )

# Get substantive vocational variables (first 16)
voc_subs <- c("W8VCQU0A", "W8VCQU0B", "W8VCQU0C", "W8VCQU0D", "W8VCQU0E", 
              "W8VCQU0F", "W8VCQU0G", "W8VCQU0H", "W8VCQU0I", "W8VCQU0J",
              "W8VCQU0K", "W8VCQU0L", "W8VCQU0M", "W8VCQU0N", "W8VCQU0O",
              "W8VCQU0P")

# Derive educ25 using rowwise with proper column access
educ25_rows <- full_data %>%
  rowwise() %>%
  mutate(
    educ25 = {
      # Get academic value
      acad <- educ25_academic
      if (is.na(acad) || acad %in% -1:-9) acad <- NA_integer_

      # Get vocational values
      voc_valids <- c()
      for (v in vocational_vars) {
        val <- get(v)  # This still might not work
        if (!is.na(val) && val >= 0 && val <= 4) {
          voc_valids <- c(voc_valids, val)
        }
      }

      # This won't work - need different approach
      return(-3)
    }
  ) %>%
  ungroup()

# Let me use a completely different approach - apply over rows
educ25_result <- apply(full_data, 1, function(row) {
  nsid <- row["NSID"]

  # Get academic value
  acad <- row["educ25_academic"]
  if (is.na(acad) || acad %in% -1:-9) acad <- NA

  # Get vocational values
  voc_valids <- c()
  for (v in voc_subs) {
    val <- row[v]
    if (!is.na(val) && val >= 0 && val <= 4) {
      voc_valids <- c(voc_valids, val)
    }
  }

  # Combine
  all_valid <- c(acad, voc_valids)
  all_valid <- all_valid[!is.na(all_valid) & all_valid >= 0 & all_valid <= 4]

  if (length(all_valid) > 0) {
    return(min(all_valid))
  } else {
    return(-3)
  }
})

full_data <- cbind(full_data, educ25 = educ25_result)
class(full_data$educ25) <- "integer"

# Derive educ32
full_data <- full_data %>%
  mutate(
    educ32 = ifelse(
      is.na(W9DANVQH) & is.na(W9DVNVQH),
      -3,
      ifelse(
        is.na(W9DANVQH) & !is.na(W9DVNVQH) & W9DVNVQH >= 0 & W9DVNVQH != -1 & W9DVNVQH != -8 & W9DVNVQH != -9,
        W9DVNVQH,
        ifelse(
          !is.na(W9DANVQH) & is.na(W9DVNVQH) & W9DANVQH >= 0 & W9DANVQH != -1 & W9DANVQH != -8 & W9DANVQH != -9,
          W9DANVQH,
          ifelse(
            !is.na(W9DANVQH) & !is.na(W9DVNVQH) & W9DANVQH >= 0 & W9DVNVQH >= 0 & W9DANVQH != -1 & W9DVNVQH != -1 & W9DANVQH != -8 & W9DVNVQH != -8 & W9DANVQH != -9 & W9DVNVQH != -9,
            pmax(W9DANVQH, W9DVNVQH),
            -3
          )
        )
      )
    )
  )

# Convert educ32 to factor
class(full_data$educ32) <- "factor"
levels(full_data$educ32) <- c(0:5, 95, 96, -1, -2, -3, -8, -9)
labels(full_data$educ32) <- c(
  "NVQ Entry Level", "NVQ Level 1", "NVQ Level 2", "NVQ Level 3", "NVQ Level 4", "NVQ Level 5",
  "Other academic qualification", "None of these qualifications",
  "Not applicable", "Not asked at fieldwork stage", "Not asked at fieldwork stage",
  "Missing information", "Refused"
)

# Derive educadtl32
academic_vars <- c("W9ACQU0A", "W9ACQU0B", "W9ACQU0C", "W9ACQU0D", "W9ACQU0E", 
                   "W9ACQU0F", "W9ACQU0G", "W9ACQU0H", "W9ACQU0I", "W9ACQU0J",
                   "W9ACQU0K", "W9ACQU0L", "W9ACQU0M", "W9ACQU0N", "W9ACQU0O",
                   "W9ACQU0P", "W9ACQU0Q", "W9ACQU0R", "W9ACQU0S", "W9ACQU0T",
                   "W9ACQU0U", "W9ACQU0V")

educadtl32_result <- apply(full_data, 1, function(row) {
  # Find first "Yes" (1)
  vals <- as.integer(row[academic_vars])
  yes_indices <- which(vals == 1)

  if (length(yes_indices) > 0) {
    return(yes_indices[1])
  } else {
    # Check for non-substantive
    non_sub <- which(vals %in% c(-3, -1, -8, -9, -2))
    if (length(non_sub) > 0) {
      return(-1)
    } else {
      return(4)
    }
  }
})

full_data <- cbind(full_data, educadtl32 = educadtl32_result)
class(full_data$educadtl32) <- "factor"
levels(full_data$educadtl32) <- c(1, 2, 3, 4, -1, -2, -3, -8, -9)
labels(full_data$educadtl32) <- c(
  "NVQ 4-5 equivalent", "NVQ 1-3 equivalent", "Entry level or no qualifications",
  "None of these qualifications", "Not applicable", "Not asked at fieldwork stage",
  "Not asked at fieldwork stage", "Don't know / insufficient information", "Refused"
)

# Derive educvdtl32
voc_vars_32 <- c("W9VCQU0A", "W9VCQU0B", "W9VCQU0C", "W9VCQU0D", "W9VCQU0E", 
                 "W9VCQU0F", "W9VCQU0G", "W9VCQU0H", "W9VCQU0I", "W9VCQU0J",
                 "W9VCQU0K", "W9VCQU0L", "W9VCQU0M", "W9VCQU0N", "W9VCQU0O",
                 "W9VCQU0P", "W9VCQU0Q", "W9VCQU0R", "W9VCQU0S", "W9VCQU0T",
                 "W9VCQU0U", "W9VCQU0V", "W9VCQU0W", "W9VCQU0X", "W9VCQU0Y",
                 "W9VCQU0Z", "W9VCQUAA", "W9VCQUAB", "W9VCQUAC", "W9VCQUAD",
                 "W9VCQUAE", "W9VCQUAF", "W9VCQUAG", "W9VCQUAH", "W9VCQUAI")

educvdtl32_result <- apply(full_data, 1, function(row) {
  vals <- as.integer(row[voc_vars_32])
  yes_indices <- which(vals == 1)

  if (length(yes_indices) > 0) {
    return(yes_indices[1])
  } else {
    non_sub <- which(vals %in% c(-3, -1, -8, -9))
    if (length(non_sub) > 0) {
      return(-1)
    } else {
      return(37)
    }
  }
})

full_data <- cbind(full_data, educvdtl32 = educvdtl32_result)
class(full_data$educvdtl32) <- "factor"
levels(full_data$educvdtl32) <- c(1:37, -1, -2, -3, -8, -9)
labels(full_data$educvdtl32) <- c(
  paste0("Vocational qual ", 1:37),
  "Not applicable", "Not asked at fieldwork stage", "Not asked at fieldwork stage",
  "Don't know / insufficient information", "Refused"
)

# Select output
output_vars <- c("NSID", "educ25", "educ32", "educadtl32", "educvdtl32")
write_csv(full_data %>% select(all_of(output_vars)), "data/output/cleaned_data.csv")

cat("Script completed successfully.\n")

